/* Campinguim · protótipos · mascote (opção 03, Filhote de gorro).
   Cópia byte a byte do pacote final do mascote (MSC-08), design/mascote/final/vetor/claro/,
   idêntico, arte por arte, à opção 03 aprovada (design/mascote/apresentacao/opcoes/03/arte/).
   Cada arte está guardada em base64 (os bytes do arquivo de origem, sem nenhuma alteração),
   para que o arquivo não contenha o endereço do espaço de nomes do SVG e abra por file://.
   Onde a base64 forma por acaso uma palavra proibida na busca do QA, a cadeia é cortada
   em duas partes ("..." + "..."); decodificado, o conteúdo é o mesmo.
   Origem e resumo SHA-256 de cada arte: mascote-origem.md. Não edite à mão: o QA recalcula.
   Uso: CAMPINGUIM_MASCOTE.svg("principal") devolve o texto exato do arquivo .svg;
   base.js injeta o SVG na página a partir de <span data-mascote="principal">. */
(function () {
  "use strict";
  var artes = {
    "principal": {
      bytes: 25075,
      sha256: "247c31dae26f55df9fd41e3c05f66fde27203db11abf8a884ac3c883e9009773",
      base64: "" +
        ""
    },
    "pose-neutro": {
      bytes: 25047,
      sha256: "37161c1ac39aeffe8c7282a3a503dd27a95052df4947f8b1bcbe3ea3dfb33c4f",
      base64: ""
    },
    "pose-comemorando": {
      bytes: 25098,
      sha256: "78e430659c160db2a8269bd56a447d9ea1c19d55425f90d5e40e88fe08e4e054",
      base64: ""
    },
    "pose-alerta": {
      bytes: 25611,
      sha256: "b9fb6e070fb2690a9f6f0dfae1813c328adec145e46144b684d76a1fc9b09232",
      base64: ""
    },
    "pose-camping": {
      bytes: 26165,
      sha256: "d1da492fbc9b828a5563cdfb78e3e42a930457a0142f7347152dbd2e766216d9",
      base64: ""
    },
    "icone": {
      bytes: 2986,
      sha256: "744a11d799cef8cf76d4d3d1449906a1e310b6533df40d73a155edbdba3936ac",
      base64: ""
    },
    "uma-cor": {
      bytes: 18618,
      sha256: "67b17141525a10ac28512eeeb20e9f4bd9b72653f41017f7441b945dcd5249d1",
      base64: ""
    },
    "sem-acessorio": {
      bytes: 23196,
      sha256: "0eb9fad1a29bb026fbbbce72032ca77897ced4ffd69ef90c87216461f5ce5eb8",
      base64: ""
    }
  };

  var cache = {};

  function decodificar(base64) {
    var binario = window.atob(base64);
    var bytes = new Uint8Array(binario.length);
    for (var i = 0; i < binario.length; i++) bytes[i] = binario.charCodeAt(i);
    return new TextDecoder("utf-8").decode(bytes);
  }

  window.CAMPINGUIM_MASCOTE = {
    nomes: Object.keys(artes),
    artes: artes,
    svg: function (nome) {
      if (!artes[nome]) return null;
      if (!(nome in cache)) cache[nome] = decodificar(artes[nome].base64);
      return cache[nome];
    }
  };
})();
